var NOBODY = {
  "entry-without-body": "an entry of the edit history has no body",
  "end-of-history": "the tick is older than the edit history GitHub keeps",
  "not-in-newest-entry": "the body kept moving"
};

// src/render/timing.ts
var RESOLVE_PARTS = [
  "dashboard",
  "config",
  "discovery",
  "records",
  "ticks",
  "opening",
  "body"
];
var NAMES2 = {
  dashboard: "reading the dashboard",
  config: "reading the config",
  discovery: "discovery",
  records: "reading deployment records",
  ticks: "judging ticks",
  opening: "opening records",
  body: "writing the body"
};
function resolveTimingLine(timing) {
  const measured = RESOLVE_PARTS.flatMap((part) => {
    const milliseconds = timing.parts[part];
    return milliseconds === undefined ? [] : [{ name: NAMES2[part], milliseconds }];
  });
  const rest = timing.total - measured.reduce((sum, { milliseconds }) => sum + milliseconds, 0);
  const named = [
    ...measured,
    ...measured.length === 0 || seconds2(rest) === "0.0" || rest < 0 ? [] : [{ name: "the rest", milliseconds: rest }]
  ];
  const parts = named.length === 0 ? "" : `: ${named.map(({ name, milliseconds }) => `${name} ${seconds2(milliseconds)} s`).join(", ")}`;
  const startup = timing.startup === undefined ? "" : ` Starting the action took ${seconds2(timing.startup)} s before that.`;
  return `Resolve took ${seconds2(timing.total)} s${parts}.${startup}`;
}
function seconds2(milliseconds) {
  return (Math.round(milliseconds / 100) / 10).toFixed(1);
}

// src/modes/resolve.ts
async function resolve3(context) {
  let handedOn = false;
  const handOn = (entries) => {
    context.setOutput("matrix", matrixOutput(entries));
    handedOn = true;
  };
  const report = { acting: false, lines: [], scanStarted: false, outsideRecords: 0 };
  const watch = stopwatch(context.now ?? (() => new Date(0)));
  const recording = {
    ...context,
    log: {
      ...context.log,
      info: (line) => {
        if (report.acting)
          report.lines.push(line);
        context.log.info(line);
      }
    }
  };
  try {
    await resolveTicks(recording, handOn, report, watch);
  } finally {
    if (!handedOn)
      handOn([]);
    if (report.acting)
      await writeRunSummary(context, report);
    if (report.acting && context.now) {
      context.log.info(resolveTimingLine({
        total: watch.total(),
        parts: watch.parts(),
        startup: context.startup
      }));
    }
  }
  return { outsideRecords: report.outsideRecords };
}
function notTheDashboardText(issue, config) {
  const text = `Issue #${issue.number} is not the open dashboard. Nothing to do.`;
  if (issue.state !== "open" || !isBotIssueWithRootMarker(issue))
    return text;
  return issue.labels.includes(config().dashboard.label) ? undefined : text;
}
async function writeRunSummary(context, report) {
  try {
    await context.log.writeSummary(resolveSummary({
      lines: report.lines,
      scanUrl: report.scanUrl,
      scanStarted: report.scanStarted
    }));
  } catch (error) {
    context.log.info(`The job summary could not be written: ${errorMessage(error)}`);
  }
}
